"""Contract-first parallel application slices. Disjoint ownership; gated integration."""
import concurrent.futures as cf
import datetime as dt
import hashlib
import json
from pathlib import Path
import signal
import uuid
from automation.council import Supervisor,MANIFEST,REVIEW,GateError,validate_manifest,source_snapshot,write_snapshot,make_diff,fingerprint,atomic_json,evaluate_staging

ROOT=Path(__file__).resolve().parents[1]
CONTRACT='''Working local PoC by 11 November 08:00 WIB. No dependency installs. Preserve existing behavior/tests. Synthetic data only. Never claim production readiness.
Store contract available in seed candidate: insert_business_record(notebook_id,kind,display_name,status), get_business_record(record_id), list_business_records(notebook_id), count_business_records(optional notebook_id). IDs generated by store, duplicate names allowed. kind person/work_item; status unknown/planned/occurred. Existing doc claims remain independent. All lookups notebook scoped.
HTTP contract: GET /api/notebooks/{id}/records => {records:[...]}; POST same => 201 {record:...}, fields kind/display_name/status, validate input and notebook, 400 invalid /404 missing notebook. POST /api/notebooks/{id}/query with question delegates to klayer.business_query.answer(store, notebook_id, question, provider). Preserve response semantics for existing docs-only questions/tests.
Business query module function answer(store,notebook_id,question,provider) returns JSON dict. For business intent return route db_only/combined/unsupported, answer status string, records list, claims list, evidence list, reason, method, trace {duration_s,route}. Evidence records carry table/id/field/source timestamp; do not invent version field. Record IDs and exact display-name matches can resolve queries; multiple same-name rows => ambiguous, never pick first. Combined evidence links document claims ONLY through exact stable record ID in source quote; never equate same-name mentions. If no exact link, explicitly insufficient evidence with record evidence; do not falsely label combined. Database status is attributed, not universal truth. Plans neither prove event occurrence nor nonoccurrence. No AI-generated SQL: closed schema, backend Store methods/parameterized statements. Natural language paraphrases should map to typed operations using Grok when provider supports it; explicit rules fallback labeled. Use existing provider helper only if necessary and honor timeout. Generic unsupported questions must abstain. Legacy docs-only ask may be delegated unchanged.
UI must let user create notebook, create independent records, see IDs/status, upload new text, query and inspect source evidence/error/method. No fixture-keyed answers. Source/doc/user strings rendered with textContent, not unsafe innerHTML. File TXT/MD reading in browser is allowed; never advertise native PDF support without parser.
Each task returns full files JSON manifest; never edits other owned files. Deliver working code, not markdown plans. Do not alter existing tests to hide defects.''' 
TASKS={
'query-engine':{'files':['klayer/business_query.py','tests/test_business_query.py'],'context':['klayer/providers.py','klayer/pipeline.py','klayer/domain.py'],'task':'Implement the new business_query module and focused behavior tests against real Store. Keep code bounded and integrate the shared API contract. Call provider planning only when relevant, typed/validated. Cover ambiguous identity, cross-notebook isolation, true DB-only and exact-ID combined evidence. Legacy docs query delegation remains unchanged.'},
'http-api':{'files':['klayer/server.py'],'context':['klayer/server.py'],'task':'Implement ONLY records GET/POST routes and query delegation per contract. Preserve all existing routes and UI serving. Validate JSON/required fields, catch Store ValueError and invalid Content-Length cleanly. Do not implement query engine or touch other files.'},
'ui-workflow':{'files':['klayer/static/index.html'],'context':['klayer/static/index.html'],'task':'Implement a polished but small Indonesian UI for complete notebook -> independent records -> new text document -> grounded query workflow. Use contract endpoints exactly. Show stable IDs, provider/fallback, progress/errors, response evidence and ambiguity. Add local TXT/MD file chooser if useful. Keep existing category correction/retry behavior. No guessed routes or unsupported features.'},
'acceptance-tests':{'files':['tests/test_business_http.py'],'context':['klayer/server.py','tests/test_flow.py'],'task':'Independently implement HTTP acceptance tests using rules provider and temporary DB via actual loopback server. Test records create/list separate from documents, duplicate names not merged, validation and scope, upload fresh nonce and repeat, query API smoke. Tests should assert meaningful contract behavior without imposing exact prose or implementation internals. Clean server shutdown/server_close/store teardown. Do not write application code.'}}


def validate_owned(root,files,owned):
    validate_manifest(root,files)
    if any(f['path'] not in owned for f in files):raise GateError('ownership_violation')
    return files


def main():
    run=ROOT/'.parallel-builds'/(dt.datetime.now().strftime('%Y%m%d-%H%M%S')+'-'+uuid.uuid4().hex[:6]);s=Supervisor(ROOT,run,max_calls=12,max_hours=2,provider_timeout=600)
    s.model_overrides={k:'grok-4.7-build-fast' for k in TASKS};s.model_overrides.update({'integration-repair':'grok-4.7-build-fast','integration-contract-review':'grok-4.7-build-fast'})
    def cancel(*_):s.cancel.set()
    signal.signal(signal.SIGTERM,cancel);signal.signal(signal.SIGINT,cancel)
    base=dict(s.origin)
    seed=ROOT/'.council-runs/20261110-212748-e5a9aa/round-01/builder.json'
    obj=json.loads(seed.read_text());validate_manifest(ROOT,obj['files'])
    # Seed is a candidate contract, not trusted acceptance. Entire merged diff is tested/reviewed.
    for f in obj['files']:base[f['path']]=f['content']
    pinned=run/'pinned-tests';write_snapshot(pinned,{k[6:]:v for k,v in s.origin.items() if k.startswith('tests/')})
    cache=ROOT/'.parallel-builds/cache';cache.mkdir(parents=True,exist_ok=True)
    ownership={path:role for role,t in TASKS.items() for path in t['files']};assert len(ownership)==sum(len(t['files']) for t in TASKS.values())
    atomic_json(run/'tasks.json',{'contract':CONTRACT,'tasks':TASKS,'seed_hash':fingerprint(base),'depends_on':{'integration':list(TASKS),'reviews':['integration_tests'],'candidate':['reviews']}})
    s.state.update(status='parallel_build',round=1);s.event('parallel-start',seed_review_status='candidate_only',context_policy='selected files + shared contract',workers=4)
    try:
        def worker(role):
            task=TASKS[role];selected={k:base[k] for k in task['context'] if k in base}
            # Only the public business-record seam, not the entire store implementation.
            store_contract=CONTRACT
            prompt=store_contract+'\nYOUR TASK\n'+task['task']+'\nEXCLUSIVE OUTPUT PATHS\n'+json.dumps(task['files'])+'\nRELEVANT SOURCE ONLY\n'+s.context(selected)
            key=hashlib.sha256((role+prompt+s.model_overrides[role]).encode()).hexdigest();cp=cache/(key+'.json')
            if cp.exists():result=json.loads(cp.read_text());s.event(role,status='cache_hit',task_hash=key)
            else:result=s.call(role,prompt,MANIFEST,run);atomic_json(cp,result)
            validate_owned(ROOT,result['files'],task['files']);return result
        changes={}
        with cf.ThreadPoolExecutor(max_workers=4) as pool:
            pending={pool.submit(worker,k):k for k in TASKS}
            for future in cf.as_completed(pending):
                role=pending[future];changes[role]=future.result();s.event('slice-ready',task=role,paths=[f['path'] for f in changes[role]['files']])
        proposed=dict(base)
        for result in changes.values():
            for f in result['files']:proposed[f['path']]=f['content']
        for attempt in range(2):
            stage=run/f'candidate-{attempt}';write_snapshot(stage,proposed);before=fingerprint(source_snapshot(stage));s.state['status']='integration_tests';s.event('integration-tests-start',attempt=attempt)
            result=evaluate_staging(stage,legacy_tests=pinned,check=s.check);atomic_json(run/f'tests-{attempt}.json',result)
            if fingerprint(source_snapshot(stage))!=before:raise GateError('tests_mutated_source')
            if not result['passed']:
                s.event('integration-tests-failed',attempt=attempt)
                if attempt:raise GateError('integration_tests_failed')
                repair=s.call('integration-repair','Repair only the integration failures below. Follow existing contract; at most three changed application/test files. Do not weaken tests or remove assertions. Return full-file JSON.\n'+CONTRACT+'\nTEST EVIDENCE\n'+json.dumps(result)+'\nCURRENT SOURCE\n'+s.context(proposed),MANIFEST,run)
                validate_manifest(ROOT,repair['files'])
                if len(repair['files'])>3:raise GateError('repair_too_large')
                for f in repair['files']:proposed[f['path']]=f['content']
                continue
            diff=make_diff(s.origin,proposed);h=hashlib.sha256(diff.encode()).hexdigest();(run/'candidate.diff').write_text(diff)
            review='Independently review exact integrated application diff. Return diff_hash '+h+'. Reject security/correctness failures, fake hybrid, unsafe scope or test weakening. Distinguish bounded remaining limitations from blockers.\nCONTRACT\n'+CONTRACT+'\nTEST RESULTS\n'+json.dumps(result)+'\nDIFF\n'+diff
            s.state['status']='parallel_reviews'
            with cf.ThreadPoolExecutor(max_workers=2) as pool:
                fs=[pool.submit(s.call,role,review+focus,REVIEW,run) for role,focus in [('integration-integrity-review','\nFocus data integrity and evidence support.'),('integration-contract-review','\nFocus API/UI/test compatibility.')]]
                reviews=[f.result() for f in fs]
            if any(r.get('diff_hash')!=h or r.get('verdict')!='approve' for r in reviews):raise GateError('integration_review_rejected')
            if fingerprint(source_snapshot(stage))!=before:raise GateError('candidate_changed_during_review')
            pointer={'release':str(stage),'source_hash':before,'diff_hash':h,'tests':'passed','reviews':'two_approve','acceptance':'live_provider_and_manual_demo_not_yet_certified'}
            atomic_json(ROOT/'.parallel-builds/latest-reviewed.json',pointer);s.state.update(status='candidate_ready',accepted=1,latest_release=str(stage));s.event('parallel-candidate-ready',**pointer);break
    except Exception as exc:s.state['status']='blocked';s.event('parallel-failed',error=str(exc)[:500]);raise
    print(run,flush=True)

if __name__=='__main__':main()
